// =============================================================================
// ГОЛОВНИЙ ВІДЖЕТ: NeonGameButton
// Спеціальна кнопка для ігрового меню з плавною анімацією перемикання станів.
// =============================================================================

class NeonGameButton extends StatelessWidget {
  final bool isActive;
  final VoidCallback? onTap;

  const NeonGameButton({
    super.key,
    required this.isActive,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: isActive ? onTap : null,
      child: AnimatedSwitcher(
        duration: const Duration(milliseconds: 300),
        child: SizedBox(
          key: ValueKey<bool>(isActive),
          // Робимо висоту трохи більшою за 52, щоб лінії влізли вертикально
          height: 102,
          width: double.infinity,
          child: SvgPicture.string(
            isActive ? _svgContinueActive : _svgContinueInactive,
            // Використовуємо fill, щоб розтягнути кнопку на всю ширину
            fit: BoxFit.fill,
          ),
        ),
      ),
    );
  }
}


