  Widget build(BuildContext context) {
    return Container(
      height: 60, // Чітко за твоїм CSS
      width: double.infinity,
      decoration: const BoxDecoration(
        color: Color(0xFF181826), // background: #181826;
        border: Border(
          top: BorderSide(
              color: Color(0xFF2B2B3B), width: 1), // border: 1px solid #2B2B3B;
        ),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        // автоматично вираховує gap: 55px
        children: [
          _buildItem(0, _homeSvg),
          _buildItem(1, _friendsSvg),
          _buildItem(2, _chatsSvg),
          _buildItem(3, _profileSvg),
        ],
      ),
    );
  }

  Widget _buildItem(int index, String svgRaw) {
    final isSelected = selectedIndex == index;
    // Визначаємо колір: активний — зелений (#00F5A0), неактивний — сірий (#8E8EA9)
    final String colorHex = isSelected ? '#00F5A0' : '#8E8EA9';

    // Підставляємо потрібний колір прямо в SVG код
    final String dynamicSvg = svgRaw.replaceAll('CURRENT_COLOR', colorHex);

    return GestureDetector(
      onTap: () => onTap(index),
      behavior: HitTestBehavior.opaque,
      child: Stack(
        clipBehavior: Clip.none, // Щоб крапка не обрізалася
        children: [
          Container(
            width: 42,
            height: 42,
            alignment: Alignment.center,
            child: SvgPicture.string(
              dynamicSvg,
              width: index == 1 ? 42 : 36,
              height: index == 1 ? 37 : 36,
            ),
          ),
          // НЕОНОВА КРАПКА
          if (index == 2 && hasUnreadMessage) // Перевіряємо індекс і стан
            Positioned(
              right: 2,
              top: 2,
              child: Container(
                width: 10,
                height: 10,
                decoration: const BoxDecoration(
                  color: Color(0xFF00F5A0),
                  shape: BoxShape.circle,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

