/// === Блискавка, не з SVG ===
class FigmaLightningIcon extends StatelessWidget {
  final double size;

  const FigmaLightningIcon({super.key, this.size = 20.0});

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: Size(size, size),
      painter: _LightningPainter(),
    );
  }
}

class _LightningPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.0 // Товщина лінії контуру
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    // Створюємо точно такий самий градієнт, як на твоєму скріншоті
    paint.shader = const LinearGradient(
      colors: [Color(0xFF00F5A0), Color(0xFF0085FF)],
      begin: Alignment.topRight,
      end: Alignment.bottomLeft,
    ).createShader(Rect.fromLTWH(0, 0, size.width, size.height));

    // Малюємо гостру блискавку по точкам (пропорційно до розміру віджета)
    final path = Path();
    path.moveTo(size.width * 0.65, size.height * 0.05); // Верхня точка
    path.lineTo(size.width * 0.20, size.height * 0.55); // Зсув вліво-вниз
    path.lineTo(size.width * 0.50, size.height * 0.55); // Внутрішній зсув вправо
    path.lineTo(size.width * 0.35, size.height * 0.95); // Нижня гостра точка
    path.lineTo(size.width * 0.80, size.height * 0.45); // Зсув вправо-вгору
    path.lineTo(size.width * 0.50, size.height * 0.45); // Внутрішній зсув вліво
    path.close(); // Повертаємось у верхню точку

    canvas.drawPath(path, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}


